using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Observer.ProbabilisticClosure.TrajectoryLaws;

internal sealed class ErasedExteriorFiltrationDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Finite exterior fields and the full posterior guard", H("Finite exterior fields and the full posterior guard"),
        Blocks(
            Describe.Lean(DescribeId.Create("window"),
                DeclarationHandle.Create("D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/ErasedExteriorFiltration.window"),
                H("The erased-center finite exterior"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("window(r,z) is the pair of original chronological Boolean blocks from -r through -1 and from one through r. The center coordinate is absent."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("field"),
                DeclarationHandle.Create("D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/ErasedExteriorFiltration.field"),
                H("The finite observation field"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("field(r) is the sigma-algebra generated by window(r)."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("information"),
                DeclarationHandle.Create("D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/ErasedExteriorFiltration.information"),
                H("One increasing exterior filtration"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("information is the natural-indexed filtration of field(r) inside the original visible process field. The transition from r+1 to r deletes one outer coordinate on each side."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("full-field"),
                DeclarationHandle.Create("D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/ErasedExteriorFiltration.full_field"),
                H("The full exterior is generated by these windows"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The supremum over all natural radii of field(r) equals the field generated by the pair of entire retained half-lines exterior. Both inclusions are proved through the actual original coordinate maps."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("finite-mean"),
                DeclarationHandle.Create("D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/ErasedExteriorFiltration.finiteMean"),
                H("The native finite exterior posterior"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every finite stationary marked presentation theta, finiteMean(theta,r) is the native regular conditional probability of X0=true given window(r), evaluated at the actual observed pair, under visibleLaw(theta)."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("no-uniform-exterior-guard"),
                DeclarationHandle.Create("D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/ErasedExteriorFiltration.no_uniform_exterior_guard"),
                H("Actual full erasure excludes a uniform strict guard"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For any finite stationary marked presentation whose actual full exterior posterior equals X0 almost surely, every event G of positive actual visible probability, epsilon>0 and starting radius r0, it is impossible that the native finiteMean(theta,r) belongs to [epsilon,1-epsilon] almost surely on G for every r>=r0. The proof uses the exact generated full field, the native conditional-distribution/conditional-expectation identity and almost-sure martingale convergence on that same measure."))), DescribeRole.Theorem))));
}
